using System;using System.IO;using System.Linq;using System.Globalization;using UnityEngine;using KSP.UI.Screens;
namespace Groundworks.FuelFire {
[KSPAddon(KSPAddon.Startup.MainMenu,true)]public class FuelRuntime:MonoBehaviour {
 public const string Version="1.0.0";public static FuelRuntime Instance;public static bool Enabled=true,FireEnabled=true,RepairsEnabled=true;public static float LeakMultiplier=1;public static int Quality=1,RegisteredParts;bool visible,conflict;Rect window=new Rect(45,90,380,365);ApplicationLauncherButton button;Texture2D icon;float statusTimer;string liveStatus="No active leaks";
 string ConfigPath{get{return Path.Combine(KSPUtil.ApplicationRootPath,"GameData/GroundworksFuelFire/PluginData/settings.cfg");}}
 void Awake(){if(Instance!=null){Destroy(gameObject);return;}Instance=this;DontDestroyOnLoad(gameObject);
 if(AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetType("Groundworks.Destruction.DestructionRuntime")!=null)){Enabled=false;conflict=true;Debug.LogError("[GW Fuel] Remove GroundworksDestruction before using standalone Fuel & Fire.");return;}
 var path=File.Exists(ConfigPath)?ConfigPath:Path.Combine(KSPUtil.ApplicationRootPath,"GameData/GroundworksFuelFire/Settings.cfg");var cfg=ConfigNode.Load(path);if(cfg!=null){var n=cfg.GetNode("GROUNDWORKS_FUEL_FIRE");bool enabled;int quality;float rate;if(n!=null){if(bool.TryParse(n.GetValue("enabled"),out enabled))Enabled=enabled;if(bool.TryParse(n.GetValue("fireEnabled"),out enabled))FireEnabled=enabled;if(bool.TryParse(n.GetValue("repairsEnabled"),out enabled))RepairsEnabled=enabled;if(float.TryParse(n.GetValue("leakMultiplier"),NumberStyles.Float,CultureInfo.InvariantCulture,out rate)&&FuelRules.Finite(rate))LeakMultiplier=Mathf.Clamp(rate,.25f,3);if(int.TryParse(n.GetValue("quality"),out quality))Quality=Mathf.Clamp(quality,0,2);}}
 FuelProfiles.Load();foreach(var ap in PartLoader.LoadedPartsList){var p=ap.partPrefab;if(p==null||p.isKerbalEVA()||ap.name.StartsWith("kerbalEVA",StringComparison.OrdinalIgnoreCase))continue;try{if(!p.Modules.Contains("GroundworksFuelLeak"))p.AddModule("GroundworksFuelLeak",true);RegisteredParts++;}catch(Exception ex){Debug.LogWarning("[GW Fuel] Skipped "+ap.name+": "+ex.Message);}}
 GameEvents.onPartWillDie.Add(PartWillDie);Debug.Log("[GW Fuel] Standalone fuel/fire ready; ordinary prefabs="+RegisteredParts+"; no custom destruction or Harmony patches.");}
 void PartWillDie(Part p){if(!Enabled||!HighLogic.LoadedSceneIsFlight||p==null||p.isKerbalEVA())return;var leak=p.FindModuleImplementing<GroundworksFuelLeak>();if(leak!=null)leak.ReleaseOnDestruction();}
 void Update(){if(button==null&&ApplicationLauncher.Ready){if(icon==null){icon=new Texture2D(32,32,TextureFormat.RGBA32,false);for(int y=0;y<32;y++)for(int x=0;x<32;x++){float width=3+(31-y)*.27f;bool flame=y>3&&y<29&&Math.Abs(x-16)<width;icon.SetPixel(x,y,flame?new Color(1,.28f+.018f*y,.05f,1):new Color(.07f,.10f,.13f,1));}icon.Apply();}button=ApplicationLauncher.Instance.AddModApplication(()=>visible=true,()=>visible=false,null,null,null,null,ApplicationLauncher.AppScenes.FLIGHT,icon);}if(HighLogic.LoadedSceneIsFlight&&Input.GetKeyDown(KeyCode.F8))visible=!visible;if(!visible||!HighLogic.LoadedSceneIsFlight)return;statusTimer+=Time.unscaledDeltaTime;if(statusTimer>1){statusTimer=0;var leaks=FlightGlobals.VesselsLoaded.Where(v=>!v.packed).SelectMany(v=>v.FindPartModulesImplementing<GroundworksFuelLeak>()).Where(m=>!m.Released&&(m.leakSeverity>0||m.reservoir.CloudKg>1e-6)).ToArray();liveStatus=Enabled?leaks.Count(m=>m.FlowKgS>0)+" leaking tanks / "+leaks.Count(m=>m.Burning)+" burning\n"+leaks.Sum(m=>m.FlowKgS).ToString("F2")+" kg/s escaping / "+FuelSpill.Active.Count+" local spills":"Simulation disabled";}}
 void OnGUI(){if(visible&&HighLogic.LoadedSceneIsFlight)window=GUILayout.Window(GetInstanceID(),window,Draw,"Groundworks Fuel & Fire");}
 void Draw(int id){GUILayout.Label("Fuel & Fire "+Version);if(conflict){GUILayout.Label("Remove GroundworksDestruction and restart KSP.");if(GUILayout.Button("Close"))visible=false;GUI.DragWindow();return;}Enabled=GUILayout.Toggle(Enabled,"Enable leak simulation");FireEnabled=GUILayout.Toggle(FireEnabled,"Allow fuel ignition and fire heating");RepairsEnabled=GUILayout.Toggle(RepairsEnabled,"Allow minor EVA engineer repairs");GUILayout.Label("Leak difficulty: "+LeakMultiplier.ToString("F2")+"x");LeakMultiplier=GUILayout.HorizontalSlider(LeakMultiplier,.25f,3);GUILayout.Label("Visual quality (does not change leak difficulty)");Quality=GUILayout.SelectionGrid(Quality,new[]{"Light","Balanced","Detailed"},3);GUILayout.Label(liveStatus);GUILayout.Label("Minor, cool, unlit leaks need one stock repair kit\nand an EVA engineer within three metres.");if(GUILayout.Button("Save and close"))SaveSettings();GUI.DragWindow();}
 public void ShowWindow(){visible=true;}
 public void SaveSettings(){Directory.CreateDirectory(Path.GetDirectoryName(ConfigPath));var root=new ConfigNode();var n=root.AddNode("GROUNDWORKS_FUEL_FIRE");n.AddValue("enabled",Enabled);n.AddValue("quality",Quality);n.AddValue("fireEnabled",FireEnabled);n.AddValue("repairsEnabled",RepairsEnabled);n.AddValue("leakMultiplier",LeakMultiplier.ToString(CultureInfo.InvariantCulture));root.Save(ConfigPath);visible=false;}
 void OnDestroy(){if(Instance!=this)return;GameEvents.onPartWillDie.Remove(PartWillDie);if(button!=null&&ApplicationLauncher.Instance!=null)ApplicationLauncher.Instance.RemoveModApplication(button);if(icon!=null)Destroy(icon);Instance=null;}
}
public class FuelParticleLifetime:MonoBehaviour {public ParticleSystem system;void OnDestroy(){if(system!=null)FloatingOrigin.UnregisterParticleSystem(system);}}
}
